import{c as t,Q as r,j as a,m as l}from"./chunks/framework.hhGiamYR.js";const s=JSON.parse('{"title":"当国务秘书拿起诗琴——关于《十年纪》，我写给意大利的挽歌","description":"在《君主论》之前，马基雅维利先用但丁三行体为意大利十年的苦难写了一部长诗。他为什么写诗？诗在他手里是另一条舌头。","frontmatter":{"date":"2026-09-27T00:00:00.000Z","title":"当国务秘书拿起诗琴——关于《十年纪》，我写给意大利的挽歌","description":"在《君主论》之前，马基雅维利先用但丁三行体为意大利十年的苦难写了一部长诗。他为什么写诗？诗在他手里是另一条舌头。"},"headers":[],"relativePath":"research/decennale-poet/index.md","filePath":"research/decennale-poet/index.md"}'),o={name:"research/decennale-poet/index.md"};function p(i,e,n,u,c,d){return r(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="当国务秘书拿起诗琴——关于《十年纪》-我写给意大利的挽歌" tabindex="-1">当国务秘书拿起诗琴——关于《十年纪》，我写给意大利的挽歌 <a class="header-anchor" href="#当国务秘书拿起诗琴——关于《十年纪》-我写给意大利的挽歌" aria-label="Permalink to &quot;当国务秘书拿起诗琴——关于《十年纪》，我写给意大利的挽歌&quot;">​</a></h1><p>人们记住我，多半是因为一本讲君主的薄册子。可我最早拿去印行、正正经经题了献辞的作品，却是一部长诗。1504 年的深秋，我把《十年纪》的第一部题献给阿拉曼诺·萨尔维亚蒂——一位起初扶持过我、后来又与我渐行渐远的佛罗伦萨政治家。</p><p>那部诗写的是意大利人十年的苦难，而我只用了十五天。献辞里我把它说得很坦率：</p><blockquote><p>📖 <strong>原文</strong>：《十年纪》第一部·拉丁文献辞 &quot;请读吧，阿拉曼诺斯，既然你吩咐写这份包含了意大利人十年苦难以及我十五天劳累的作品。&quot; — 尼科洛·马基雅维利，1504年11月8日，佛罗伦萨</p><ul><li>全文：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/01-%E5%8D%81%E5%B9%B4%E7%BA%AA.md" target="_blank" rel="noreferrer">01-十年纪.md</a></li></ul></blockquote><p>十五天写尽十年，不是因为我下笔有多快，而是那十年里意大利的伤口已经多到无需构思。我只要照着时间，把查理八世如何翻过阿尔卑斯、梅迪奇家如何把要塞割给法国人、比萨如何脱离佛罗伦萨、法国与西班牙如何瓜分那波利——一件件记下来，诗自然就沉了下去。史料早就把经过摆好了，我做的只是给它配上但丁的韵脚。</p><p>第二部开头，我给自己定下了调子：</p><blockquote><p>📖 <strong>原文</strong>：《十年纪》第二部 &quot;我将吟唱意大利的苦难，/ 它们经历了过去的两个五年 / 在对她抱有敌意的星辰之下。&quot;</p><ul><li>全文：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/02-%E5%8D%81%E5%B9%B4%E7%BA%AA.md" target="_blank" rel="noreferrer">02-十年纪.md</a></li></ul></blockquote><p>&quot;敌意的星辰&quot;，这是我写史与写诗时都不肯放过的一个字眼。意大利不是被一个敌人打垮的，她是被法国、西班牙、神圣罗马帝国轮番碾过的；而每一次外敌进来，几乎都有一个意大利人自己先替他们开了门。洛多维科·斯福尔扎为了夺米兰，把查理八世请了进来；亚历山大六世为了自己的私生子，又向前去征讨那波利的法军让开了路。所以我在诗里写&quot;当她内部不和时，意大利为高卢人敞开了路&quot;——这行字，到今天我也无意收回。</p><p>第三部是另一种光景。它是 1514 年前后写的，那时我已被罢官，回到乡下，杜门封笔了一段时间。重新提笔时，我这么写：</p><blockquote><p>📖 <strong>原文</strong>：《十年纪》第三部 &quot;严重的事件、狂乱的行为……当我杜门封笔归于沉默之后……我的歌声将会是充满泪水，尽管我几乎因为痛苦而变得渐渐丧魂失魄。&quot;</p><ul><li>全文：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/03-%E5%8D%81%E5%B9%B4%E7%BA%AA.md" target="_blank" rel="noreferrer">03-十年纪.md</a></li></ul></blockquote><p>读者若有心，会察觉这三部诗的语气在变。第一部是应人之邀，第二部是旁观者记史，第三部却是一个丢了职位的人，在沉默之后重新开口。诗还是那首关于意大利的诗，只是写诗的人已经不再站在维琪奥宫的窗口。</p><p>这部长诗里，有一段我至今重读仍会停住。我写到一个叫安东尼奥·贾科米尼的佛罗伦萨将领，他为我们打赢过 1505 年的仗，后来却落到无人问津的田地：</p><blockquote><p>📖 <strong>原文</strong>：《十年纪》第三部 &quot;如今他被遗忘和诋毁，躺在 / 他的家里，穷困、衰老，双目 / 失明，机运对好人是这般不喜！&quot;</p><ul><li>全文：<a href="https://niflhum.top/machiavelli-library/library/machiavelli/drama-poetry/03-%E5%8D%81%E5%B9%B4%E7%BA%AA.md" target="_blank" rel="noreferrer">03-十年纪.md</a></li></ul></blockquote><p>我几乎没有加一句评价。只把&quot;机运对好人是这般不喜&quot;这一行摆在那里，读者自会明白我想说什么：在这个世上，德性与回报之间没有契约。这也正是我后来在《君主论》里反复咀嚼的那个话题——机运夺走一半，人只能守住剩下的一半。</p><p>那么，我为什么写诗？一个国务秘书，手边有写不完的急件，为什么还要费心思去押但丁的韵？答案藏在这份工作的性质里。急件有它的规矩：我向十人委员会报告公爵说了什么、我怀疑他想要什么，字字都要留有余地，好让执政官们拿去做判断。诗没有这种束缚。在诗里，我可以替整个意大利的命运哭一场，可以把一个被遗忘的老将扶起来重新站到读者面前。急件是给少数人看的；诗，是给所有还活着的人看的。</p><p>文学于我，从来不是逃避。它是我在外交急件之外的另一条舌头——当报告里不便直说的话，就让诗去说。</p><p>尼科洛·马基雅维利，圣卡夏诺</p>',17)])])}const h=t(o,[["render",p]]);export{s as __pageData,h as default};
